@'
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {parseManifest} from './packages/core/src/domain/manifest.ts';
import {parseSkillDocument, documentName, documentDescription} from './packages/core/src/domain/skill-document.ts';
const dir='skills/reactive-and-virtual-thread-selection';
const {manifest, issues}=parseManifest(fs.readFileSync(dir+'/skill.yaml','utf8'),{source:dir+'/skill.yaml',strict:true});
assert.deepEqual(issues,[]);
const main=fs.readFileSync(dir+'/SKILL.md','utf8');
const doc=parseSkillDocument(main);
assert.equal(documentName(doc),manifest.name);
assert.equal(documentDescription(doc),manifest.description);
assert.match(fs.readFileSync(dir+'/skill.yaml','utf8'),/^version: 1\.3\.6$/m);
const files=fs.readdirSync(dir,{recursive:true}).filter(x=>fs.statSync(path.join(dir,x)).isFile());
assert.deepEqual(files.map(x=>x.replaceAll('\\','/')).sort(),['SKILL.md','references/decision-matrix.md','references/framework-execution-models.md','skill.yaml']);
for(const p of manifest.files) assert.ok(fs.existsSync(path.join(dir,p)),p);
let links=0;
const routed=new Set([...manifest.dependencies.map(x=>x.name),...manifest.suggests]);
for(const file of files.filter(x=>x.endsWith('.md'))) {
 const text=fs.readFileSync(path.join(dir,file),'utf8');
 for(const [,ref] of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
  if(!/^[a-z]+:\/\//i.test(ref) && !ref.startsWith('#')) {assert.ok(fs.existsSync(path.resolve(dir,path.dirname(file),ref.split('#')[0])),ref);links++;}
 }
 for(const [,name] of text.matchAll(/`([a-z][a-z0-9]*(?:-[a-z0-9]+)+)`/g)) {
  if(fs.existsSync(path.join('skills',name,'SKILL.md'))) assert.ok(routed.has(name),name);
 }
}
for(const ref of files.filter(x=>x.startsWith('references'))) assert.ok(main.includes(ref.replaceAll('\\','/')),ref);
console.log(JSON.stringify({strictManifestIssues:issues.length,files:files.length,metadataEqual:true,relativeLinks:links,routes:'pass',version:manifest.version}));
